const msg = $json.message ?? {};

if (msg.is_outgoing === true) {
  return [];
}

const telegramMessageId = msg.id ?? null;
const telegramUserId = msg.sender_id?.user_id ?? null;
const telegramChatId = msg.chat_id ?? null;

const replyToMessageId =
  msg.reply_to?.message_id ??
  msg.reply_to_message_id ??
  msg.reply_to_message?.id ??
  msg.reply_to_message?.message_id ??
  msg.reply_to?.id ??
  null;

if (telegramMessageId === null) {
  return [];
}

if (telegramUserId === null && telegramChatId === null) {
  return [];
}

const content = msg.content ?? {};
const contentType = content._ ?? content['@type'] ?? 'unknown';

let messageType = 'other';
let text = '';

let hasAttachment = false;
let fileId = '';
let fileName = '';
let mimeType = '';
let fileSizeBytes = 0;
let attachmentKind = '';

switch (contentType) {
  case 'messageText':
    messageType = 'text';
    text = content.text?.text ?? '';
    break;

  case 'messagePhoto': {
    messageType = 'photo';
    text =
      content.caption?.text ??
      content.text?.text ??
      '';

    const sizes = Array.isArray(content.photo?.sizes)
      ? content.photo.sizes
      : [];

    let largest = null;

    for (const size of sizes) {
      const f = size?.photo;
      if (!f?.id) continue;

      const bytes = Number(
        f.size ??
        f.expected_size ??
        0
      );

      const largestBytes = Number(
        largest?.size ??
        largest?.expected_size ??
        0
      );

      if (!largest || bytes >= largestBytes) {
        largest = f;
      }
    }

    if (largest?.id) {
      hasAttachment = true;
      attachmentKind = 'photo';
      fileId = String(largest.id);
      fileSizeBytes = Number(
        largest.size ??
        largest.expected_size ??
        0
      );
      mimeType = 'image/jpeg';
      fileName =
        `telegram_photo_${telegramMessageId}.jpg`;
    }

    break;
  }

  case 'messageDocument': {
    messageType = 'document';

    const doc = content.document ?? {};
    const file = doc.document ?? {};

    text =
      content.caption?.text ??
      doc.file_name ??
      '';

    if (file?.id) {
      hasAttachment = true;
      attachmentKind = 'document';
      fileId = String(file.id);
      fileSizeBytes = Number(
        file.size ??
        file.expected_size ??
        0
      );
      fileName =
        String(
          doc.file_name ??
          `telegram_file_${telegramMessageId}`
        );
      mimeType =
        String(
          doc.mime_type ??
          'application/octet-stream'
        );
    }

    break;
  }

  case 'messageVideo':
  case 'messageAnimation':
  case 'messageVideoNote':
    messageType = 'video';
    text = content.caption?.text ?? '';
    break;

  case 'messageVoiceNote':
    messageType = 'voice';
    text = content.caption?.text ?? '';
    break;

  case 'messageAudio':
    messageType = 'audio';
    text =
      content.caption?.text ??
      content.audio?.file_name ??
      '';
    break;

  case 'messageSticker':
    messageType = 'sticker';
    text = content.sticker?.emoji ?? '';
    break;
}

const rawDate = Number(msg.date ?? 0);

let telegramCreatedAt = new Date().toISOString();

if (Number.isFinite(rawDate) && rawDate > 0) {
  telegramCreatedAt =
    new Date(rawDate * 1000).toISOString();
}

const maxFileBytes = 100 * 1024 * 1024;

const fileSizeKnown =
  hasAttachment &&
  Number.isFinite(fileSizeBytes) &&
  fileSizeBytes > 0;

const fileTooLarge =
  fileSizeKnown &&
  fileSizeBytes > maxFileBytes;

const safeToDownload =
  !hasAttachment ||
  (
    fileSizeKnown &&
    !fileTooLarge
  );

return [{
  json: {
    telegram_message_id: String(telegramMessageId),

    telegram_user_id:
      telegramUserId === null
        ? ''
        : String(telegramUserId),

    telegram_chat_id:
      telegramChatId === null
        ? ''
        : String(telegramChatId),

    reply_to_message_id:
      replyToMessageId === null
        ? ''
        : String(replyToMessageId),

    message_type: messageType,
    text,

    telegram_created_at: telegramCreatedAt,

    raw_content_type: contentType,
    raw_message_json: JSON.stringify(msg),

    has_attachment: hasAttachment,
    attachment_kind: attachmentKind,
    file_id: fileId,
    file_name: fileName,
    mime_type: mimeType,
    file_size_bytes: fileSizeBytes,
    file_size_mb:
      fileSizeBytes > 0
        ? Number(
            (fileSizeBytes / 1024 / 1024).toFixed(2)
          )
        : 0,
    file_size_known: fileSizeKnown,
    file_too_large: fileTooLarge,
    safe_to_download: safeToDownload,
    max_file_size_bytes: maxFileBytes,
    max_file_size_mb: 100
  }
}];

const row = $json;
const incoming =
  $('Normalize Incoming').first().json;

if (!row.dialog_id) {
  return [];
}

const count =
  Number(row.matching_dialogs ?? 0);

if (count > 1) {
  throw new Error(
    `Найдено несколько маршрутизируемых V3-диалогов из Active-задач для одного Telegram чата. ` +
    `Нельзя однозначно маршрутизировать сообщение. matches=${count}`
  );
}

return [{
  json: {
    ...row,
    ...incoming
  }
}];

function sql(v) {
  return String(v ?? '').replace(/'/g, "''");
}

function bigint(v, label) {
  const s = String(v ?? '').trim();

  if (!/^-?\d+$/.test(s)) {
    throw new Error(`${label} is not an integer: ${s}`);
  }

  return s;
}

function optionName(v) {
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    return v.name ?? String(v);
  }

  return String(v ?? '');
}

function multiNames(v) {
  if (!Array.isArray(v)) {
    return [];
  }

  return v
    .map(optionName)
    .filter(Boolean);
}

function hhmm(v, fallback) {
  const m = String(v || fallback).match(
    /^(\d{1,2}):(\d{2})/
  );

  if (!m) {
    throw new Error(`Invalid time: ${v}`);
  }

  return {
    h: Number(m[1]),
    m: Number(m[2])
  };
}

const task = $json;
const incoming = $('Validate Routing').item.json;

const zone =
  optionName(task.timezone) ||
  'Europe/Moscow';

const workDaysRaw =
  multiNames(task.work_days);

const workDays =
  workDaysRaw.length
    ? workDaysRaw
    : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];

const start =
  hhmm(task.work_start, '09:00');

const end =
  hhmm(task.work_end, '19:00');

let delayMin =
  Math.max(
    0,
    Math.floor(
      Number(task.delay_min_sec ?? 20)
    )
  );

let delayMax =
  Math.max(
    delayMin,
    Math.floor(
      Number(
        task.delay_max_sec ??
        delayMin
      )
    )
  );

// Каждый новый message получает новую случайную человеческую паузу.
// Если pending process_inbound уже есть,
// run_at будет перенесён на новое время.
const delaySec =
  delayMin +
  Math.floor(
    Math.random() *
    (delayMax - delayMin + 1)
  );

const now =
  $now.setZone(zone);

const dayMap = {
  Mon: 1,
  Tue: 2,
  Wed: 3,
  Thu: 4,
  Fri: 5,
  Sat: 6,
  Sun: 7
};

const allowed =
  new Set(
    workDays
      .map(x => dayMap[x])
      .filter(Boolean)
  );

if (!allowed.size) {
  [1, 2, 3, 4, 5]
    .forEach(x => allowed.add(x));
}

let runAt = null;

// Поддерживает обычные и ночные окна.
for (
  let offset = -1;
  offset <= 8 && !runAt;
  offset++
) {
  const day =
    now
      .startOf('day')
      .plus({ days: offset });

  if (!allowed.has(day.weekday)) {
    continue;
  }

  let windowStart =
    day.set({
      hour: start.h,
      minute: start.m,
      second: 0,
      millisecond: 0
    });

  let windowEnd =
    day.set({
      hour: end.h,
      minute: end.m,
      second: 0,
      millisecond: 0
    });

  if (windowEnd <= windowStart) {
    windowEnd =
      windowEnd.plus({ days: 1 });
  }

  if (now >= windowEnd) {
    continue;
  }

  const base =
    now > windowStart
      ? now
      : windowStart;

  const candidate =
    base.plus({
      seconds: delaySec
    });

  if (candidate < windowEnd) {
    runAt = candidate;
  }
}

if (!runAt) {
  throw new Error(
    'Could not calculate process_inbound run_at'
  );
}

const runAtIso =
  runAt
    .toUTC()
    .toISO();

const dialogId =
  bigint(
    incoming.dialog_id,
    'dialog_id'
  );

const telegramMessageId =
  bigint(
    incoming.telegram_message_id,
    'telegram_message_id'
  );

const messageText =
  sql(incoming.text);

const messageType =
  sql(incoming.message_type);

const telegramCreatedAt =
  sql(incoming.telegram_created_at);

const rawMessageJson =
  sql(incoming.raw_message_json);

const airtableDialogId =
  sql(incoming.airtable_dialog_id);

const airtableTaskId =
  sql(incoming.airtable_task_id);

const q = `
WITH inserted_message AS (

  INSERT INTO agent_v3.messages (
    dialog_id,
    telegram_message_id,
    direction,
    sender_type,
    message_type,
    text,
    telegram_created_at,
    metadata
  )

  VALUES (
    ${dialogId},
    ${telegramMessageId},
    'inbound',
    'user',
    '${messageType}',
    NULLIF('${messageText}', ''),
    '${telegramCreatedAt}'::timestamptz,

    jsonb_build_object(
      'source',
      'telepilot',
      'raw_message',
      '${rawMessageJson}'::jsonb
    )
  )

  ON CONFLICT (
    dialog_id,
    telegram_message_id
  )
  WHERE telegram_message_id IS NOT NULL

  DO NOTHING

  RETURNING
    id,
    dialog_id,
    telegram_message_id
),

cancel_followups AS (

  UPDATE agent_v3.events
  SET
    status = 'cancelled',
    locked_at = NULL,
    updated_at = NOW()
  WHERE dialog_id = ${dialogId}
    AND event_type = 'followup'
    AND status = 'pending'
  RETURNING id
),

scheduled_event AS (

  INSERT INTO agent_v3.events (
    dialog_id,
    event_type,
    run_at,
    status,
    payload
  )

  SELECT
    im.dialog_id,
    'process_inbound',
    '${sql(runAtIso)}'::timestamptz,
    'pending',

    jsonb_build_object(
      'airtable_task_id',
      '${airtableTaskId}',
      'airtable_dialog_id',
      '${airtableDialogId}',
      'last_message_id',
      im.id,
      'last_telegram_message_id',
      im.telegram_message_id
    )

  FROM inserted_message im

  ON CONFLICT (
    dialog_id,
    event_type
  )
  WHERE
    status = 'pending'
    AND event_type IN (
      'start_dialog',
      'process_inbound',
      'followup'
    )

  DO UPDATE SET
    run_at = EXCLUDED.run_at,
    payload =
      agent_v3.events.payload ||
      EXCLUDED.payload,
    updated_at = NOW()

  RETURNING
    id,
    dialog_id,
    run_at
),

updated_dialog AS (

  UPDATE agent_v3.dialogs d

  SET
    -- На входящем сообщении sender_id.user_id уже относится к собеседнику.
    telegram_user_id =
      COALESCE(
        NULLIF('${sql(incoming.telegram_user_id)}', '')::bigint,
        d.telegram_user_id
      ),

    telegram_chat_id =
      COALESCE(
        NULLIF('${sql(incoming.telegram_chat_id)}', '')::bigint,
        d.telegram_chat_id
      ),

    status = 'active',
    waiting_for = NULL,
    followup_count = 0,

    last_activity_at = NOW(),
    last_inbound_at = NOW(),

    next_action_at = (
      SELECT se.run_at
      FROM scheduled_event se
      LIMIT 1
    ),

    updated_at = NOW()

  WHERE
    d.id = ${dialogId}
    AND EXISTS (
      SELECT 1
      FROM inserted_message
    )

  RETURNING
    d.id,
    d.airtable_dialog_id,
    d.airtable_task_id,
    d.status
)

SELECT
  ud.id AS dialog_id,
  ud.airtable_dialog_id,
  ud.airtable_task_id,
  ud.status AS dialog_status,

  se.id AS event_id,
  se.run_at AS next_action_at,

  im.id AS message_db_id,
  im.telegram_message_id

FROM updated_dialog ud

JOIN inserted_message im
  ON im.dialog_id = ud.id

JOIN scheduled_event se
  ON se.dialog_id = ud.id;
`;

return [{
  json: {
    sql_query: q,

    dialog_id: incoming.dialog_id,
    airtable_dialog_id:
      incoming.airtable_dialog_id,
    airtable_task_id:
      incoming.airtable_task_id,

    telegram_message_id:
      incoming.telegram_message_id,

    message_type:
      incoming.message_type,

    text:
      incoming.text,

    delay_sec:
      delaySec,

    next_action_at:
      runAtIso
  }
}];

function sql(v) {
  return String(v ?? '').replace(/'/g, "''");
}

function bigint(v, label) {
  const s = String(v ?? '').trim();

  if (!/^-?\d+$/.test(s)) {
    throw new Error(`${label} is not an integer: ${s}`);
  }

  return s;
}

function optionName(v) {
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    return v.name ?? String(v);
  }
  return String(v ?? '');
}

function multiNames(v) {
  if (!Array.isArray(v)) return [];
  return v.map(optionName).filter(Boolean);
}

function hhmm(v, fallback) {
  const m = String(v || fallback).match(/^(\d{1,2}):(\d{2})/);

  if (!m) {
    throw new Error(`Invalid time: ${v}`);
  }

  return {
    h: Number(m[1]),
    m: Number(m[2])
  };
}

const task = $json;
const request = $('Find Owner Reply v2').item.json;
const incoming = $('Normalize Incoming').item.json;

const answer =
  String(incoming.text ?? '')
    .trim();

if (!answer) {
  throw new Error(
    'Ответ ответственного должен содержать текст'
  );
}


const answerScope =
  request.answer_scope === 'task'
    ? 'task'
    : 'dialog';

const factDialogSql =
  answerScope === 'task'
    ? 'NULL'
    : String(request.dialog_id);

const factText =
  `Вопрос: ${String(request.owner_question ?? '').trim()}\nОтвет: ${answer}`;

const zone =
  optionName(task.timezone) ||
  'Europe/Moscow';

const workDaysRaw =
  multiNames(task.work_days);

const workDays =
  workDaysRaw.length
    ? workDaysRaw
    : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];

const start =
  hhmm(task.work_start, '09:00');

const end =
  hhmm(task.work_end, '19:00');

let delayMin =
  Math.max(
    0,
    Math.floor(
      Number(task.delay_min_sec ?? 20)
    )
  );

let delayMax =
  Math.max(
    delayMin,
    Math.floor(
      Number(task.delay_max_sec ?? delayMin)
    )
  );

const delaySec =
  delayMin +
  Math.floor(
    Math.random() *
    (delayMax - delayMin + 1)
  );

const now =
  $now.setZone(zone);

const dayMap = {
  Mon: 1,
  Tue: 2,
  Wed: 3,
  Thu: 4,
  Fri: 5,
  Sat: 6,
  Sun: 7
};

const allowed =
  new Set(
    workDays
      .map(x => dayMap[x])
      .filter(Boolean)
  );

if (!allowed.size) {
  [1, 2, 3, 4, 5]
    .forEach(x => allowed.add(x));
}

let runAt = null;

for (
  let offset = -1;
  offset <= 8 && !runAt;
  offset++
) {
  const day =
    now.startOf('day')
      .plus({ days: offset });

  if (!allowed.has(day.weekday)) {
    continue;
  }

  let ws =
    day.set({
      hour: start.h,
      minute: start.m,
      second: 0,
      millisecond: 0
    });

  let we =
    day.set({
      hour: end.h,
      minute: end.m,
      second: 0,
      millisecond: 0
    });

  if (we <= ws) {
    we = we.plus({ days: 1 });
  }

  if (now >= we) {
    continue;
  }

  const base =
    now > ws ? now : ws;

  const candidate =
    base.plus({
      seconds: delaySec
    });

  if (candidate < we) {
    runAt = candidate;
  }
}

if (!runAt) {
  throw new Error(
    'Could not calculate owner_answer run_at'
  );
}

const runAtIso =
  runAt.toUTC().toISO();

const requestId =
  bigint(
    request.owner_request_id,
    'owner_request_id'
  );

const dialogId =
  bigint(
    request.dialog_id,
    'dialog_id'
  );

const ownerAnswerMessageId =
  bigint(
    incoming.telegram_message_id,
    'owner_answer_telegram_message_id'
  );

const adminUserId =
  String(incoming.telegram_user_id ?? '')
    .trim();

const adminChatId =
  String(incoming.telegram_chat_id ?? '')
    .trim();

const q = `
WITH answer_request AS (

  UPDATE agent_v3.owner_requests
  SET
    status = 'answered',
    answer = '${sql(answer)}',
    owner_answer_telegram_message_id =
      ${ownerAnswerMessageId},
    answered_at = NOW(),
    updated_at = NOW()
  WHERE id = ${requestId}
    AND status = 'open'
  RETURNING id
),

save_fact AS (

  INSERT INTO agent_v3.facts (
    airtable_task_id,
    dialog_id,
    scope,
    category,
    fact_text,
    source_type,
    is_confirmed,
    is_active,
    metadata
  )

  SELECT
    '${sql(request.airtable_task_id)}',
    ${factDialogSql},
    '${answerScope}',
    'owner_answer',
    '${sql(factText)}',
    'owner',
    TRUE,
    TRUE,
    jsonb_build_object(
      'owner_request_id',
      ${requestId},
      'question',
      '${sql(request.owner_question)}',
      'answer_scope',
      '${answerScope}',
      'source_dialog_id',
      ${dialogId}
    )

  FROM answer_request

  RETURNING id
),

schedule_event AS (

  INSERT INTO agent_v3.events (
    dialog_id,
    event_type,
    run_at,
    status,
    payload
  )

  SELECT
    ${dialogId},
    'owner_answer',
    '${sql(runAtIso)}'::timestamptz,
    'pending',
    jsonb_build_object(
      'owner_request_id',
      ${requestId},
      'airtable_task_id',
      '${sql(request.airtable_task_id)}',
      'airtable_dialog_id',
      '${sql(request.airtable_dialog_id)}',
      'answer_scope',
      '${answerScope}'
    )

  FROM answer_request

  RETURNING id, run_at
),

update_dialog AS (

  UPDATE agent_v3.dialogs
  SET
    status = 'active',
    waiting_for = NULL,
    next_action_at = (
      SELECT run_at
      FROM schedule_event
      LIMIT 1
    ),
    last_activity_at = NOW(),
    updated_at = NOW()
  WHERE id = ${dialogId}
    AND EXISTS (
      SELECT 1
      FROM answer_request
    )
  RETURNING id
)

SELECT
  ${requestId}::bigint
    AS owner_request_id,

  ${dialogId}::bigint
    AS dialog_id,

  '${sql(request.airtable_owner_request_id)}'::text
    AS airtable_owner_request_id,

  '${sql(request.airtable_task_id)}'::text
    AS airtable_task_id,

  '${sql(request.airtable_dialog_id)}'::text
    AS airtable_dialog_id,

  '${sql(answer)}'::text
    AS answer,

  '${sql(adminUserId)}'::text
    AS admin_telegram_user_id,

  '${sql(adminChatId)}'::text
    AS admin_telegram_chat_id,

  '${sql(runAtIso)}'::timestamptz
    AS next_action_at,

  '${answerScope}'::text
    AS answer_scope;
`;

return [{
  json: {
    sql_query: q,

    owner_request_id:
      request.owner_request_id,

    airtable_owner_request_id:
      request.airtable_owner_request_id,

    airtable_task_id:
      request.airtable_task_id,

    airtable_dialog_id:
      request.airtable_dialog_id,

    answer,

    admin_telegram_user_id:
      adminUserId,

    admin_telegram_chat_id:
      adminChatId,

    next_action_at:
      runAtIso,

    answer_scope:
      answerScope,

    delay_sec:
      delaySec
  }
}];

const x = $json;

let message = '';

if (x.file_too_large === true) {
  message =
    `Файл слишком большой (${x.file_size_mb} МБ). ` +
    `Пожалуйста, пришлите файл размером не более 100 МБ.`;
} else {
  message =
    'Не удалось определить размер файла до скачивания. ' +
    'Пожалуйста, пришлите файл размером не более 100 МБ как обычный документ.';
}

return [{
  json: {
    ...x,
    rejection_message: message
  }
}];

const routing = $input.first().json;
const incoming = $('Normalize Incoming').first().json;

return [{
  json: {
    ...incoming,
    ...routing,

    // Force attachment fields from the original normalized Telegram message.
    has_attachment: incoming.has_attachment ?? false,
    attachment_kind: incoming.attachment_kind ?? '',
    file_id: incoming.file_id ?? '',
    file_name: incoming.file_name ?? '',
    mime_type: incoming.mime_type ?? '',
    file_size_bytes: incoming.file_size_bytes ?? 0,
    file_size_mb: incoming.file_size_mb ?? 0,
    file_size_known: incoming.file_size_known ?? false,
    file_too_large: incoming.file_too_large ?? false,
    safe_to_download: incoming.safe_to_download ?? false,
    max_file_size_bytes: incoming.max_file_size_bytes ?? (100 * 1024 * 1024),
    max_file_size_mb: 100
  }
}];

const fs = require('fs');
const path = require('path');

const item = $input.first();
const source = $('Restore Attachment Context').first().json;

const filePath =
  item.json.file?.local?.path ??
  item.json.local?.path;

if (!filePath) {
  throw new Error('TelePilot не вернул file.local.path');
}

if (!fs.existsSync(filePath)) {
  throw new Error(`Файл не найден: ${filePath}`);
}

const buffer = fs.readFileSync(filePath);

const maxSize = 100 * 1024 * 1024;

if (buffer.length > maxSize) {
  throw new Error(
    `Файл больше 100 МБ: ${(buffer.length / 1024 / 1024).toFixed(2)} МБ`
  );
}

const fileName =
  source.file_name ||
  path.basename(filePath) ||
  `telegram_file_${source.telegram_message_id}`;

let contentType =
  String(source.mime_type ?? '').trim();

if (
  !contentType ||
  contentType === 'application/octet-stream' ||
  contentType === 'application/binary'
) {
  const ext = path.extname(fileName).toLowerCase();

  const mimeByExt = {
    '.pdf': 'application/pdf',
    '.csv': 'text/csv',
    '.txt': 'text/plain',
    '.json': 'application/json',
    '.xml': 'application/xml',

    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.png': 'image/png',
    '.webp': 'image/webp',
    '.gif': 'image/gif',

    '.doc': 'application/msword',
    '.docx':
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',

    '.xls': 'application/vnd.ms-excel',
    '.xlsx':
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',

    '.ppt': 'application/vnd.ms-powerpoint',
    '.pptx':
      'application/vnd.openxmlformats-officedocument.presentationml.presentation',

    '.zip': 'application/zip',
    '.rar': 'application/vnd.rar',
    '.7z': 'application/x-7z-compressed',

    '.mp3': 'audio/mpeg',
    '.wav': 'audio/wav',
    '.ogg': 'audio/ogg',
    '.mp4': 'video/mp4'
  };

  contentType =
    mimeByExt[ext] ||
    'application/octet-stream';
}

return [{
  json: {
    ...source,
    file_name: fileName,
    content_type: contentType,
    actual_file_size: buffer.length,
    actual_file_size_mb:
      Number((buffer.length / 1024 / 1024).toFixed(2)),
    file_base64: buffer.toString('base64')
  }
}];

const record = $input.first().json;
const cached =
  $('Cache File in PostgreSQL').first().json;
const source =
  $('Restore Attachment Context').first().json;

const token =
  String(cached.token ?? '').trim();

if (!token) {
  throw new Error('PostgreSQL cache did not return token');
}

const fileName =
  String(source.file_name || 'attachment.bin');

const newUrl =
  'YOUR_N8N_PUBLIC_BASE_URL/webhook/YOUR_V2_FILE_DOWNLOAD_PATH/' +
  token +
  '?filename=' +
  encodeURIComponent(fileName);

const current =
  String(record.file_urls ?? '').trim();

const existing =
  current
    ? (current.match(/https?:\/\/[^\s,;]+/gi) ?? [])
        .map(x => x.trim())
        .filter(Boolean)
    : [];

existing.push(newUrl);

const uniqueUrls =
  [...new Set(existing)];

return [{
  json: {
    ...source,
    airtable_dialog_id:
      source.airtable_dialog_id,
    file_urls:
      uniqueUrls.join('\n'),
    files_sync_pending:
      true,
    new_postgres_file_url:
      newUrl,
    postgres_file_token:
      token,
    file_size_bytes:
      cached.file_size_bytes,
    files_count:
      uniqueUrls.length
  }
}];

const task = $json;
const dialog = $('Get Dialog — Large File').first().json;
const incoming = $('Restore Attachment Context').first().json;

const adminChatId =
  String(task.admin_telegram_chat_id ?? '').trim();

if (!/^-?\d+$/.test(adminChatId)) {
  throw new Error(
    `У задачи ${task.Name_task ?? incoming.airtable_task_id} ` +
    `не заполнен admin_telegram_chat_id`
  );
}

const personName =
  String(
    dialog.person_name ??
    incoming.telegram_username ??
    incoming.telegram_user_id ??
    'неизвестный пользователь'
  ).trim();

const username =
  String(dialog.telegram_username ?? '').trim();

const taskName =
  String(
    task.Name_task ??
    incoming.airtable_task_id ??
    'без названия'
  ).trim();

const sizeKnown =
  incoming.file_size_known === true &&
  Number(incoming.file_size_bytes || 0) > 0;

const sizeText =
  sizeKnown
    ? `${Number(incoming.file_size_mb || 0).toFixed(2)} МБ`
    : 'размер не определён заранее';

const fileName =
  String(
    incoming.file_name ||
    incoming.text ||
    'файл'
  ).trim();

const userLabel =
  username
    ? `${personName} (${username})`
    : personName;

const notice =
  `V3 · крупный файл передан администратору\n\n` +
  `Задача: ${taskName}\n` +
  `Собеседник: ${userLabel}\n` +
  `Telegram user_id: ${incoming.telegram_user_id || '—'}\n` +
  `Файл: ${fileName}\n` +
  `Размер: ${sizeText}\n\n` +
  `Оригинальный файл будет переслан следующим сообщением.`;

return {
  json: {
    ...incoming,
    admin_chat_id: adminChatId,
    task_name: taskName,
    person_name: personName,
    telegram_username: username,
    admin_notice: notice,
    large_file_forwarded_to_admin: true
  }
};

const x = $('Prepare Large File Admin Notice').first().json;

const originalText =
  String(x.text ?? '').trim();

const systemNote =
  '[Системно: вложение больше 5 МБ (или размер заранее не определён). ' +
  'Оригинальное Telegram-сообщение с файлом автоматически переслано ' +
  'ответственному администратору по задаче. Не проси пользователя ' +
  'отправлять файл повторно и не утверждай, что файл сохранён в Airtable.]';

return {
  json: {
    ...x,
    text:
      originalText
        ? `${originalText}\n\n${systemNote}`
        : systemNote
  }
};
